from abc import ABC, abstractmethod
from typing import Dict, List, Any

class Renderer(ABC):
    @abstractmethod
    def render(self, data: List[Dict[str, Any]]) -> str:
        pass

class CSVRenderer(Renderer):
    def render(self, data: List[Dict[str, Any]]) -> str:
        header = ','.join(data[0].keys())
        lines = [header] + [','.join(str(v) for v in row.values()) for row in data]
        return '\n'.join(lines)

class JSONRenderer(Renderer):
    def render(self, data: List[Dict[str, Any]]) -> str:
        import json
        return json.dumps(data, indent=2)

class HTMLRenderer(Renderer):
    def render(self, data: List[Dict[str, Any]]) -> str:
        headers = ''.join(f'<th>{k}</th>' for k in data[0].keys())
        rows_html = ''.join(
            f'<tr>{"".join(f'<td>{v}</td>' for v in row.values())}</tr>'
            for row in data
        )
        return f'<table><thead><tr>{headers}</tr></thead><tbody>{rows_html}</tbody></table>'

FORMAT_REGISTRY = {
    'csv': CSVRenderer(),
    'json': JSONRenderer(),
    'html': HTMLRenderer(),
}

class ReportGenerator:
    def generate(self, data: List[Dict[str, Any]], format: str) -> str:
        renderer = FORMAT_REGISTRY.get(format)
        if renderer is None:
            raise ValueError(f'Unknown format: {format}')
        return renderer.render(data)
